defmodule SuchConfigCore.Generators.AIContext.Common do
  @moduledoc """
  Common/shared sections for AI context generation.

  Contains sections that are used regardless of project type:
  - Header and footer
  - Overview
  - Contributing
  - Security
  - Git workflow
  - CI/CD
  - Pre-commit hooks
  - Key files
  - Restrictions
  """

  alias SuchConfigCore.Generators.AIContext.Helpers

  def build_header(project_data) do
    project_name = project_data[:project_name] || "Project"

    """
    # #{project_name}

    > Auto-generated by SuchConfig Workflow Wizard
    > Regenerate anytime with `suchconfig wizard generate`
    """
  end

  def build_footer do
    """
    ---

    *Generated by [SuchConfig Workflow Wizard](https://suchconfig.io)*
    """
  end

  def build_overview(project_data) do
    description = extract_description(project_data)
    project_type = Helpers.format_project_type(project_data[:project_type])
    framework = project_data[:framework]

    overview_parts = []
    overview_parts = if description && description != "", do: overview_parts ++ [description], else: overview_parts

    overview_parts =
      if framework, do: overview_parts ++ ["Built with #{Helpers.format_framework(framework)}."], else: overview_parts

    overview_parts = if project_type, do: overview_parts ++ ["#{project_type} project."], else: overview_parts

    if length(overview_parts) > 0 do
      """
      ## Overview

      #{Enum.join(overview_parts, " ")}
      """
    else
      nil
    end
  end

  def build_project_structure(project_data) do
    path = project_data[:path]

    if path && File.dir?(path) do
      structure = Helpers.detect_directory_structure(path)

      if structure != "" do
        """
        ## Project Structure

        ```
        #{structure}
        ```
        """
      else
        nil
      end
    else
      nil
    end
  end

  def build_contributing(project_data) do
    files = project_data[:files] || []
    contributing = Helpers.find_file(files, :contributing)

    if contributing do
      ways = contributing[:ways_to_contribute] || []

      ways_section =
        if length(ways) > 0 do
          items = Enum.map_join(ways, "\n", &"- #{&1}")
          "### Ways to Contribute\n\n#{items}"
        else
          nil
        end

      if ways_section do
        """
        ## Contributing

        This project has a CONTRIBUTING.md with detailed guidelines.

        #{ways_section}

        > 📖 See `CONTRIBUTING.md` for full contribution guidelines
        """
      else
        """
        ## Contributing

        This project has a CONTRIBUTING.md with detailed guidelines.

        > 📖 See `CONTRIBUTING.md` for full contribution guidelines
        """
      end
    else
      nil
    end
  end

  def build_security(project_data) do
    files = project_data[:files] || []
    security = Helpers.find_file(files, :security_md)

    if security && security[:has_content] do
      sections = []

      sections =
        if security[:security_email],
          do: sections ++ ["- **Security Contact**: #{security[:security_email]}"],
          else: sections

      sections =
        if security[:reporting_guidelines],
          do: sections ++ ["- **How to Report**: #{security[:reporting_guidelines]}"],
          else: sections

      sections =
        if security[:response_time],
          do: sections ++ ["- **Response Time**: #{security[:response_time]}"],
          else: sections

      sections =
        if security[:discourages_public_disclosure],
          do: sections ++ ["- ⚠️ **Do not publicly disclose** vulnerabilities before contacting the security team"],
          else: sections

      out_of_scope_section =
        if length(security[:out_of_scope] || []) > 0 do
          items = Enum.map_join(security[:out_of_scope], "\n", &"  - #{&1}")
          "\n\n### Out of Scope\n\n#{items}"
        else
          ""
        end

      if length(sections) > 0 do
        """
        ## Security

        This project has a SECURITY.md with vulnerability reporting guidelines.

        #{Enum.join(sections, "\n")}#{out_of_scope_section}
        """
      else
        nil
      end
    else
      nil
    end
  end

  def build_pre_commit_hooks(project_data) do
    files = project_data[:files] || []
    pre_commit = Helpers.find_file(files, :pre_commit_config)

    if pre_commit && pre_commit[:has_content] do
      hooks = pre_commit[:hook_ids] || []
      repos = pre_commit[:repos] || []

      sections = []
      hook_categories = categorize_hooks(hooks)

      sections =
        if length(hook_categories[:formatting] || []) > 0 do
          items = Enum.map(hook_categories[:formatting], fn h -> "- `#{h}` - Code formatting" end)
          sections ++ ["### Formatting Hooks\n#{Enum.join(items, "\n")}"]
        else
          sections
        end

      sections =
        if length(hook_categories[:linting] || []) > 0 do
          items = Enum.map(hook_categories[:linting], fn h -> "- `#{h}` - Code linting" end)
          sections ++ ["### Linting Hooks\n#{Enum.join(items, "\n")}"]
        else
          sections
        end

      sections =
        if length(hook_categories[:type_checking] || []) > 0 do
          items = Enum.map(hook_categories[:type_checking], fn h -> "- `#{h}` - Type checking" end)
          sections ++ ["### Type Checking\n#{Enum.join(items, "\n")}"]
        else
          sections
        end

      sections =
        if length(hook_categories[:general] || []) > 0 do
          items = Enum.map(hook_categories[:general], fn h -> "- `#{h}`" end)
          sections ++ ["### General Hooks\n#{Enum.join(items, "\n")}"]
        else
          sections
        end

      repo_info =
        if length(repos) > 0 do
          repo_items = repos |> Enum.take(10) |> Enum.map(fn r -> "- #{r}" end)
          "\n### Hook Sources\n#{Enum.join(repo_items, "\n")}"
        else
          ""
        end

      if length(sections) > 0 do
        """
        ## Pre-commit Hooks

        This project uses pre-commit to enforce code quality. Run `pre-commit install` to set up the hooks.

        #{Enum.join(sections, "\n\n")}#{repo_info}

        > Run `pre-commit run --all-files` to check all files
        """
      else
        nil
      end
    else
      nil
    end
  end

  def build_ci_cd(project_data) do
    files = project_data[:files] || []
    path = project_data[:path]

    github_actions = Helpers.detect_github_actions(path)
    has_github = Enum.any?(files, fn f -> f[:name] in [".github", "workflows"] end) || length(github_actions) > 0

    if has_github || length(github_actions) > 0 do
      sections = []

      sections =
        if length(github_actions) > 0 do
          workflow_items =
            github_actions
            |> Enum.take(15)
            |> Enum.map(fn w -> "- **#{w[:name]}** - #{w[:description]}" end)

          sections ++ ["### GitHub Actions Workflows\n\n#{Enum.join(workflow_items, "\n")}"]
        else
          sections ++ ["### GitHub Actions\n\nThis project uses GitHub Actions for CI/CD."]
        end

      if length(sections) > 0 do
        """
        ## CI/CD

        #{Enum.join(sections, "\n\n")}

        > Always ensure CI passes before submitting a pull request
        """
      else
        nil
      end
    else
      nil
    end
  end

  def build_coding_standards(project_data) do
    project_type = project_data[:project_type]
    code_quality = project_data[:code_quality] || %{}
    git_workflow = project_data[:git_workflow] || %{}

    standards = []

    standards =
      if project_type in [:ruby, :mixed_ruby] do
        cond do
          code_quality[:rubocop] ->
            standards ++ ["- RuboCop enabled for code linting - Run with `bundle exec rubocop`"]

          code_quality[:standard_rb] ->
            standards ++ ["- Standard enabled for code linting - Run with `bundle exec standardrb`"]

          true ->
            standards
        end
      else
        if code_quality[:eslint] do
          extends = (code_quality[:eslint][:extends] || []) |> Enum.take(3) |> Enum.join(", ")

          if extends != "",
            do: standards ++ ["- ESLint configuration extends: #{extends}"],
            else: standards ++ ["- ESLint enabled for code linting"]
        else
          standards
        end
      end

    standards =
      if project_type in [:ruby, :mixed_ruby] do
        standards
      else
        cond do
          code_quality[:prettier] -> standards ++ ["- Prettier enabled for code formatting"]
          code_quality[:biome] -> standards ++ ["- Biome enabled for linting and formatting"]
          true -> standards
        end
      end

    standards =
      if code_quality[:typescript] do
        ts = code_quality[:typescript]

        if ts[:strict],
          do: standards ++ ["- TypeScript with strict mode enabled"],
          else: standards ++ ["- TypeScript enabled"]
      else
        standards
      end

    standards =
      if git_workflow[:commitlint] do
        extends = (git_workflow[:commitlint][:extends] || []) |> Enum.take(2) |> Enum.join(", ")

        if extends != "",
          do: standards ++ ["- Commit messages validated with commitlint (#{extends})"],
          else: standards ++ ["- Commit messages validated with commitlint"]
      else
        standards
      end

    if length(standards) > 0 do
      """
      ## Coding Standards

      #{Enum.join(standards, "\n")}
      """
    else
      nil
    end
  end

  def build_testing(project_data) do
    testing = project_data[:testing_config] || %{}

    if testing[:has_testing] do
      sections = []

      sections =
        if testing[:vitest] do
          sections ++ ["- **Unit Tests**: Vitest - Run with `npm test` or `pnpm test`"]
        else
          if testing[:jest], do: sections ++ ["- **Unit Tests**: Jest - Run with `npm test`"], else: sections
        end

      sections =
        if testing[:cypress], do: sections ++ ["- **E2E Tests**: Cypress - Run with `npm run cypress`"], else: sections

      sections =
        if testing[:playwright],
          do: sections ++ ["- **E2E Tests**: Playwright - Run with `npx playwright test`"],
          else: sections

      sections =
        if testing[:has_storybook],
          do: sections ++ ["- **Component Documentation**: Storybook - Run with `npm run storybook`"],
          else: sections

      if length(sections) > 0 do
        """
        ## Testing

        #{Enum.join(sections, "\n")}
        """
      else
        nil
      end
    else
      nil
    end
  end

  def build_git_workflow(project_data) do
    git_workflow = project_data[:git_workflow] || %{}
    ci_config = project_data[:ci_config] || %{}

    sections = []

    sections =
      if git_workflow[:has_git_hooks] do
        hooks = git_workflow[:husky_hooks] || []
        hook_names = Enum.map_join(hooks, ", ", & &1[:hook])

        if hook_names != "",
          do: sections ++ ["- **Git Hooks**: #{hook_names} (via Husky)"],
          else: sections ++ ["- **Git Hooks**: Configured"]
      else
        sections
      end

    sections =
      if ci_config[:has_ci] do
        ci_platforms = []

        ci_platforms =
          if length(ci_config[:github_actions] || []) > 0, do: ci_platforms ++ ["GitHub Actions"], else: ci_platforms

        ci_platforms = if ci_config[:gitlab_ci], do: ci_platforms ++ ["GitLab CI"], else: ci_platforms
        ci_platforms = if ci_config[:circleci], do: ci_platforms ++ ["CircleCI"], else: ci_platforms

        if length(ci_platforms) > 0,
          do: sections ++ ["- **CI/CD**: #{Enum.join(ci_platforms, ", ")}"],
          else: sections ++ ["- **CI/CD**: Configured"]
      else
        sections
      end

    sections =
      if git_workflow[:codeowners], do: sections ++ ["- **Code Owners**: CODEOWNERS file configured"], else: sections

    sections =
      if git_workflow[:pr_template],
        do: sections ++ ["- **PR Template**: Pull request template configured"],
        else: sections

    if length(sections) > 0 do
      """
      ## Git Workflow

      #{Enum.join(sections, "\n")}
      """
    else
      nil
    end
  end

  def build_key_files(project_data) do
    files = project_data[:files] || []
    project_type = project_data[:project_type]

    key_files = []

    key_files =
      if Helpers.has_file?(files, :gemfile), do: key_files ++ ["- `Gemfile` - Ruby gem dependencies"], else: key_files

    key_files =
      if Helpers.has_file?(files, :rakefile), do: key_files ++ ["- `Rakefile` - Rake task definitions"], else: key_files

    gemspec = Helpers.find_file(files, :gemspec)

    key_files =
      if gemspec do
        gem_name = gemspec[:name] || "project"
        key_files ++ ["- `#{gem_name}.gemspec` - Gem specification"]
      else
        key_files
      end

    key_files =
      if Helpers.has_file?(files, :ruby_version),
        do: key_files ++ ["- `.ruby-version` - Required Ruby version"],
        else: key_files

    key_files =
      if Helpers.has_file?(files, :package_json) and project_type not in [:ruby, :mixed_ruby],
        do: key_files ++ ["- `package.json` - Project dependencies and scripts"],
        else: key_files

    key_files =
      if Helpers.has_file?(files, :tsconfig),
        do: key_files ++ ["- `tsconfig.json` - TypeScript configuration"],
        else: key_files

    key_files =
      cond do
        Helpers.has_file?(files, :drizzle_config) ->
          key_files ++ ["- `drizzle.config.*` - Database schema configuration"]

        Helpers.has_file?(files, :prisma_schema) ->
          key_files ++ ["- `prisma/schema.prisma` - Database schema"]

        Helpers.has_file?(files, :schema_rb) ->
          key_files ++ ["- `db/schema.rb` - Database schema snapshot"]

        true ->
          key_files
      end

    key_files =
      if Helpers.has_file?(files, :routes_rb),
        do: key_files ++ ["- `config/routes.rb` - Rails route definitions"],
        else: key_files

    key_files =
      if Helpers.has_file?(files, :env_example),
        do: key_files ++ ["- `.env.example` - Required environment variables"],
        else: key_files

    key_files =
      if Helpers.has_file?(files, :dockerfile),
        do: key_files ++ ["- `Dockerfile` - Container configuration"],
        else: key_files

    key_files =
      if Helpers.has_file?(files, :agents_md),
        do: key_files ++ ["- `AGENTS.md` - AI agent development guidelines"],
        else: key_files

    key_files =
      if Helpers.has_file?(files, :contributing),
        do: key_files ++ ["- `CONTRIBUTING.md` - Contribution guidelines"],
        else: key_files

    key_files =
      if Helpers.has_file?(files, :security_md),
        do: key_files ++ ["- `SECURITY.md` - Security policy and vulnerability reporting"],
        else: key_files

    key_files =
      if Helpers.has_file?(files, :pyproject),
        do: key_files ++ ["- `pyproject.toml` - Python project configuration"],
        else: key_files

    key_files =
      if Helpers.has_file?(files, :pre_commit_config),
        do: key_files ++ ["- `.pre-commit-config.yaml` - Pre-commit hooks configuration"],
        else: key_files

    license_file = Helpers.find_file(files, :license)

    key_files =
      if license_file do
        license_type = license_file[:license_type] || "Unknown"
        key_files ++ ["- `LICENSE` - #{license_type} license"]
      else
        key_files
      end

    citation_file = Helpers.find_file(files, :citation_cff)

    key_files =
      if citation_file,
        do: key_files ++ ["- `CITATION.cff` - Citation metadata for academic references"],
        else: key_files

    req_files = Helpers.filter_files(files, :requirements_txt)

    key_files =
      if length(req_files) > 1 do
        req_types =
          req_files
          |> Enum.map(fn f -> f[:req_type] end)
          |> Enum.reject(&(&1 == :main))
          |> Enum.map_join(", ", &to_string/1)

        key_files ++ ["- `requirements*.txt` - Python dependencies (main, #{req_types})"]
      else
        if length(req_files) == 1, do: key_files ++ ["- `requirements.txt` - Python dependencies"], else: key_files
      end

    if length(key_files) > 0 do
      """
      ## Key Files

      #{Enum.join(key_files, "\n")}
      """
    else
      nil
    end
  end

  def build_agents_commands(project_data) do
    files = project_data[:files] || []
    agents_md = Helpers.find_file(files, :agents_md)

    if agents_md && length(agents_md[:commands] || []) > 0 do
      commands = agents_md[:commands]

      cmd_rows =
        Enum.map_join(commands, "\n", fn cmd ->
          "| `#{cmd[:command]}` | #{cmd[:description]} |"
        end)

      """
      ## Agent Commands (from AGENTS.md)

      | Command | Description |
      |---------|-------------|
      #{cmd_rows}
      """
    else
      nil
    end
  end

  def build_agents_code_style(project_data) do
    files = project_data[:files] || []
    agents_md = Helpers.find_file(files, :agents_md)

    if agents_md && length(agents_md[:code_style] || []) > 0 do
      styles = agents_md[:code_style]

      style_items =
        Enum.map_join(styles, "\n", fn style ->
          "- **#{style[:category]}**: #{style[:guideline]}"
        end)

      """
      ## Code Style Guidelines (from AGENTS.md)

      #{style_items}
      """
    else
      nil
    end
  end

  defp extract_description(project_data) do
    files = project_data[:files] || []
    package_json = Helpers.find_file(files, :package_json)
    pyproject = Helpers.find_file(files, :pyproject)
    gemspec = Helpers.find_file(files, :gemspec)
    readme = Helpers.find_file(files, :readme)

    cond do
      gemspec && gemspec[:description] -> gemspec[:description]
      gemspec && gemspec[:summary] -> gemspec[:summary]
      package_json && package_json[:description] -> package_json[:description]
      pyproject && pyproject[:description] -> pyproject[:description]
      readme && readme[:title] -> readme[:title]
      true -> nil
    end
  end

  defp categorize_hooks(hooks) do
    formatting = ["black", "autopep8", "yapf", "isort", "prettier", "end-of-file-fixer", "trailing-whitespace"]
    linting = ["ruff", "ruff-format", "flake8", "pylint", "eslint", "check-yaml", "check-json", "check-toml"]
    type_checking = ["mypy", "pyright", "typescript"]

    %{
      formatting: Enum.filter(hooks, fn h -> String.downcase(h) in formatting end),
      linting: Enum.filter(hooks, fn h -> String.downcase(h) in linting end),
      type_checking: Enum.filter(hooks, fn h -> String.downcase(h) in type_checking end),
      general: Enum.reject(hooks, fn h -> String.downcase(h) in (formatting ++ linting ++ type_checking) end)
    }
  end
end
